def test_get_sysctl():
    class FakeModule(object):
        def __init__(self):
            self.command = None
            self.warnings = []

        def get_bin_path(self, command):
            assert command == 'sysctl'
            return '/sbin/sysctl'

        def run_command(self, command):
            self.command = command
            return (
                0,
                'kernel.hostname = test-host\n'
                'vm.swappiness: 10\n'
                'kernel.core_pattern = first line\n'
                ' second line\n'
                ' third line\n',
                '',
            )

        def warn(self, message):
            self.warnings.append(message)

    module = FakeModule()

    result = get_sysctl(module, ['kernel', 'vm'])

    assert module.command == ['/sbin/sysctl', 'kernel', 'vm']
    assert module.warnings == []
    assert result == {
        'kernel.hostname': 'test-host',
        'vm.swappiness': '10',
        'kernel.core_pattern': 'first line\n second line\n third line',
    }
